// 基础约束（平台团队定义）
#Deployment: {
    apiVersion: "apps/v1"
    kind:       "Deployment"
    metadata: {
        name:      string
        namespace: string | *"default"
        labels: [string]: string
    }
    spec: {
        replicas: int & >=1 & <=100  // 约束：1-100
        selector: matchLabels: [string]: string
        template: spec: containers: [...#Container]
    }
}

#Container: {
    name:  string
    image: string
    resources: {
        requests: {cpu: string, memory: string}
        limits:   {cpu: string, memory: string}
    }
}

// 开发者配置（统一后自动验证）
myApp: #Deployment & {
    metadata: name: "my-app"
    spec: {
        replicas: 3
        selector: matchLabels: app: "my-app"
        template: spec: containers: [{
            name:  "app"
            image: "registry.example.com/my-app:v1"
            resources: {
                requests: {cpu: "500m", memory: "512Mi"}
                limits:   {cpu: "1", memory: "1Gi"}
            }
        }]
    }
}
// 如果 replicas: 0 或 replicas: 200，cue vet 会报错

// schemas/platform.cue
// 🟢 低风险：平台配置 Schema
package schemas

import "list"

// 平台级 Deployment 约束
#PlatformDeployment: {
    apiVersion: "apps/v1"
    kind:       "Deployment"
    metadata: {
        name:      =~"^[a-z][a-z0-9-]{2,62}$"  // 命名规范
        namespace: string
        labels: {
            "app.kubernetes.io/name":       string
            "app.kubernetes.io/version":    string
            "app.kubernetes.io/managed-by": "cue"
            "team":                          string
        }
        annotations?: [string]: string
    }
    spec: {
        replicas: int & >=1 & <=50
        revisionHistoryLimit: int | *3
        strategy: {
            type: "RollingUpdate"
            rollingUpdate: {
                maxUnavailable: int | string | *0
                maxSurge:       int | string | *"25%"
            }
        }
        selector: matchLabels: "app.kubernetes.io/name": metadata.name
        template: {
            metadata: labels: metadata.labels
            spec: {
                // 安全约束
                securityContext: {
                    runAsNonRoot: true
                    runAsUser:    int & >1000
                    fsGroup:      int & >1000
                }
                // 资源限制必须设置
                containers: [...#SecureContainer]
                // 不允许 hostNetwork/hostPID
                hostNetwork?: false
                hostPID?:     false
            }
        }
    }
}

#SecureContainer: {
    name:  string
    image: =~"^registry\\.example\\.com/"  // 必须使用内部 Registry
    securityContext: {
        allowPrivilegeEscalation: false
        readOnlyRootFilesystem:   true
        capabilities: drop: ["ALL"]
    }
    resources: {
        requests: {
            cpu:    =~"^[0-9]+m?$"
            memory: =~"^[0-9]+(Mi|Gi)$"
        }
        limits: {
            cpu:    =~"^[0-9]+m?$"
            memory: =~"^[0-9]+(Mi|Gi)$"
        }
    }
    // 健康检查必须配置
    livenessProbe: _
    readinessProbe: _
}

// teams/team-backend/api-server.cue
// 🟢 低风险：团队应用配置
package team_backend

import "platform-config/schemas"

apiServer: schemas.#PlatformDeployment & {
    metadata: {
        name:      "api-server"
        namespace: "team-backend"
        labels: {
            "app.kubernetes.io/name":    "api-server"
            "app.kubernetes.io/version": "2.1.0"
            "team":                      "backend"
        }
    }
    spec: {
        replicas: 3
        template: spec: containers: [{
            name:  "api"
            image: "registry.example.com/backend/api-server:2.1.0"
            ports: [{containerPort: 8080, protocol: "TCP"}]
            resources: {
                requests: {cpu: "500m", memory: "512Mi"}
                limits:   {cpu: "1", memory: "1Gi"}
            }
            livenessProbe: {
                httpGet: {path: "/healthz", port: 8080}
                initialDelaySeconds: 10
                periodSeconds:       15
            }
            readinessProbe: {
                httpGet: {path: "/ready", port: 8080}
                initialDelaySeconds: 5
                periodSeconds:       10
            }
            env: [
                {name: "LOG_LEVEL", value: "info"},
                {name: "DB_HOST", value: "postgres.team-backend.svc"},
            ]
        }]
    }
}

// environments/production.cue
// 🟡 中风险：生产环境覆盖
package environments

import "platform-config/teams/team-backend"

// 生产环境覆盖
production: team-backend.apiServer & {
    spec: {
        replicas: 5  // 生产环境更多副本
        template: spec: containers: [{
            resources: {
                requests: {cpu: "1", memory: "1Gi"}
                limits:   {cpu: "2", memory: "2Gi"}
            }
            env: [
                {name: "LOG_LEVEL", value: "warn"},
            ]
        }]
    }
}
